WITH input AS (SELECT jsonb_array_elements('[{"slug":"agricultural-land","old":"يشمل الأراضي الصالحة للزراعة والمحاصيل الدائمة والمراعي الدائمة.","description":"يعرض مساحة الأراضي الزراعية نسبة إلى مساحة اليابسة، بما يشمل أراضي المحاصيل المؤقتة والدائمة والمراعي الدائمة حسب تصنيف المصدر.\n\nلماذا تهم المقارنة؟\nيساعد على فهم طبيعة استخدام الأراضي والحيز المتاح للأنشطة الزراعية والرعوية، ويتيح مناقشة تباين الموارد والتضاريس بين الدول.\n\nكيف تقرأ الترتيب؟\nقارن اليمن باقتصادات ومناخات مختلفة بحذر؛ ارتفاع النسبة قد يعكس اتساع المراعي لا ارتفاع الإنتاجية. تُستكمل المقارنة بغلة الحبوب والمياه والري.\n\nحدود القراءة:\nلا تعني النسبة أن كل الأراضي المذكورة تزرع فعلياً كل سنة أو أن المياه متاحة لها. كما لا تقيس ملكية الأرض أو نوعية التربة أو حجم الإنتاج الغذائي."},{"slug":"agriculture-value","old":"يشمل الزراعة والحراجة وصيد الأسماك؛ الحصة الأكبر ليست حكماً على التنمية.","description":"القيمة المضافة للزراعة والغابات والصيد من الناتج المحلي هي نصيب هذه الأنشطة من القيمة الاقتصادية الإجمالية للبلد في السنة.\n\nلماذا تهم المقارنة؟\nتُظهر مدى وزن القطاع الأولي في الاقتصاد، وهي مفيدة لمقارنة بنية الإنتاج ودور الأنشطة الريفية والساحلية في اليمن والدول الأخرى.\n\nكيف تقرأ الترتيب؟\nالقيمة النسبية الأعلى لا تعني دائماً قطاعاً أكثر إنتاجية؛ فقد ترتفع الحصة عندما تتراجع الصناعة والخدمات. من الأفضل قراءتها مع القيمة المطلقة وإنتاجية العمل والتوظيف.\n\nحدود القراءة:\nليست نسبة العاملين في الزراعة أو حصة الغذاء المنتج محلياً، ولا تشير وحدها إلى نوعية التقنيات الزراعية أو الأمن الغذائي."},{"slug":"broadband","old":"اشتراكات الإنترنت الثابت عالي السرعة لكل مئة شخص.","description":"يقيس عدد اشتراكات الإنترنت الثابت عريض النطاق لكل مئة شخص، وفق تعريف خطوط الاتصالات الثابتة الداخلة في المصدر.\n\nلماذا تهم المقارنة؟\nيساعد على وصف مدى انتشار الاشتراكات الثابتة التي تدعم الاتصال المنزلي والمؤسسي، ويمكن مقارنته بأنماط الاتصال الخلوي واستخدام الإنترنت عموماً.\n\nكيف تقرأ الترتيب؟\nانظر إلى قيمة اليمن والوحدة قبل مقارنة المرتبة؛ لأن المؤشر يحصي الاشتراكات وليس السرعات. قد تختلف أهمية الاتصال الثابت بين البلدان التي تعتمد على شبكات الهاتف المحمول بدرجات مختلفة.\n\nحدود القراءة:\nلا يقيس عدد مستخدمي الإنترنت أو سرعة التحميل أو السعر أو الجودة مباشرة. قد يستفيد عدة أشخاص من اشتراك واحد، بينما تمتلك بعض المنشآت اشتراكات متعددة."},{"slug":"cereal-yield","old":"إنتاج الحبوب لكل هكتار محصود؛ يتأثر بنوع المحصول والمناخ.","description":"تُقاس غلة الحبوب بكمية الإنتاج المحصودة بالكيلوغرام لكل هكتار، وفق أنواع الحبوب والمساحات المشمولة في المصدر.\n\nلماذا تهم المقارنة؟\nتوضح جانباً من إنتاجية المساحات المحصودة مقارنة بالدول الأخرى، وتساعد في مناقشة آثار الري والبذور والظروف المناخية وطرق الزراعة.\n\nكيف تقرأ الترتيب؟\nاقرأ اليمن والدول الأخرى وفق سنة مشتركة ونوع المحاصيل المشمولة. قد يختلف المتوسط الوطني إذا تغيرت تركيبة الحبوب المزروعة حتى مع ثبات إنتاجية محصول بعينه.\n\nحدود القراءة:\nلا يساوي المؤشر إجمالي إنتاج الحبوب الوطني أو نسبة الاكتفاء الذاتي أو أرباح المزارعين. الغلة العالية لا تثبت أن الري مستدام أو أن المزارعين يملكون أرضاً واسعة."},{"slug":"clean-cooking","old":"السكان الذين يعتمدون أساساً على وقود وتقنيات نظيفة للطهي.","description":"يقيس نسبة السكان الذين يعتمدون أساساً على وقود وتقنيات تُصنف نظيفة للطهي ضمن المعايير الصحية والبيئية المعتمدة للمؤشر.\n\nلماذا تهم المقارنة؟\nيساعد على تقدير التعرض المحتمل لتلوث الهواء المنزلي الناتج عن الطهي التقليدي، ويفيد في مناقشة الطاقة المنزلية والصحة والتكلفة.\n\nكيف تقرأ الترتيب؟\nقارن القيم بين البلدان وسنواتها المشتركة، مع الانتباه إلى أنواع الوقود والتجهيزات المستخدمة. قد لا تتطابق النسبة مع انتشار الكهرباء أو ألواح الطاقة الشمسية.\n\nحدود القراءة:\nلا تقيس النسبة جودة تهوية المنزل أو جميع مصادر تلوث الهواء أو سعر الوقود، ولا تثبت أن كل من يستخدم وقوداً مصنفاً نظيفاً يحصل على خدمة آمنة دائماً."},{"slug":"drinking-water","old":"السكان الذين يستخدمون خدمات مياه شرب أساسية على الأقل.","description":"يقيس نسبة السكان الذين يستخدمون خدمة مياه شرب أساسية على الأقل حسب تعريف الرصد المشترك، والذي يميز المصادر المحسنة ومدة جمع المياه.\n\nلماذا تهم المقارنة؟\nتوضح المقارنة حجم الوصول إلى مصادر مياه شرب مصنفة ضمن الحد الأساسي، وهو أمر مهم للصحة اليومية ولعبء نقل المياه على الأسر.\n\nكيف تقرأ الترتيب؟\nعند قراءة اليمن والدول الأخرى، تحقق من سنة المصدر ومن معيار الخدمة الأساسي، وقارن أيضاً مؤشرات الصرف الصحي. تشابه النسب لا يعني تشابه جودة المياه أو انتظام التزويد.\n\nحدود القراءة:\nلا تثبت النسبة أن مياه المصدر خالية من التلوث أو متاحة باستمرار، ولا تساوي نسبة من لديهم شبكة منزلية أو خدمة مياه مدارة بأمان."},{"slug":"education-spending","old":"الإنفاق الحكومي على التعليم؛ حجم الإنفاق وحده لا يقيس جودة المخرجات.","description":"يقيس الإنفاق الحكومي على التعليم كنسبة من الناتج المحلي الإجمالي، وفق ما يتضمنه تعريف التعليم والإنفاق العام في بيانات المصدر.\n\nلماذا تهم المقارنة؟\nيوضح وزن التمويل العام للتعليم مقارنة بحجم الاقتصاد، ويمكن أن يساعد في مناقشة الموارد المتاحة للمدارس والمعلمين والتجهيزات. الأهمية الحقيقية تظهر عندما تتكامل الأرقام مع نتائج التعلم والعدالة في التوزيع.\n\nكيف تقرأ الترتيب؟\nقارن اليمن بدول أخرى في سنة مشتركة، ثم افحص حجم الإنفاق الفعلي وقيمة الناتج. ارتفاع نسبة التعليم قد ينتج عن زيادة الإنفاق أو عن تراجع الناتج المحلي، لذلك قد تختلف الدلالة بحسب السياق.\n\nحدود القراءة:\nلا يثبت حجم الحصة وحده جودة التعليم أو وصول الفتيات والفتيان إلى المدارس، وقد تختلف مكونات ميزانيات التعليم والسنوات المتاحة. المؤشر لا يقيس إنفاق الأسر مباشرة."},{"slug":"electricity","old":"الحصول على الكهرباء لا يعني استمرار الخدمة أو جودتها.","description":"يعبر عن حصة السكان الذين لديهم إمكانية الوصول إلى الكهرباء وفق تعريف قاعدة الرصد الدولية، وليس عن ساعات استمرار التيار الكهربائي.\n\nلماذا تهم المقارنة؟\nالمقارنة تساعد على تقدير مدى الوصول إلى خدمة مهمة للدراسة والعمل والصحة، لكنها تحتاج إلى استكمال ببيانات الاعتمادية والتكلفة ونوعية مصدر الكهرباء.\n\nكيف تقرأ الترتيب؟\nقارن اليمن بدول أخرى على سنة قياس واحدة، ثم افصل بين نمو إمكانية الوصول وبين تحسن التغذية الفعلية. الترتيب الأعلى في الوصول لا يحدد أي نظام كهربائي أكثر استقراراً.\n\nحدود القراءة:\nلا يخبر المؤشر عن عدد ساعات الانقطاع أو قدرة الأسر على تحمل السعر أو مصدر الكهرباء أو فروق المحافظات. ولا يصح الاستنتاج منه وحده بأن أزمة الكهرباء انتهت."},{"slug":"employment","old":"تقديرات منظمة العمل الدولية؛ النسبة لا تقيس الأجر أو جودة الوظيفة.","description":"نسبة المشتغلين إلى السكان تعبر عن حصة الأشخاص بعمر 15 سنة فأكثر الذين لديهم عمل بحسب تعريف المصدر، من إجمالي السكان في هذه الفئة العمرية.\n\nلماذا تهم المقارنة؟\nتظهر مدى استفادة السكان في سن العمل من فرص التشغيل، وتكمل معدلات البطالة والمشاركة في قوة العمل.\n\nكيف تقرأ الترتيب؟\nعند مقارنة اليمن بالدول الأخرى تحقق من معيار العمل المعتمد، وانظر إلى تفاوت الأعمار والجنسين. يمكن أن ترتفع نسبة المشتغلين مع استمرار ضعف الأجور أو كثرة العمل الهش.\n\nحدود القراءة:\nلا يقيس هذا المؤشر الأجر أو الحماية الاجتماعية أو عدد ساعات العمل الكافية، ولا يحدد ما إذا كانت الوظيفة رسمية أو مستقرة أو ذات إنتاجية مرتفعة."},{"slug":"female-participation","old":"تقديرات منظمة العمل الدولية المنمذجة للمشاركة الاقتصادية للنساء.","description":"يقيس نسبة النساء بعمر 15 سنة فأكثر اللواتي يعملن أو يبحثن عن عمل ومتاحات له ضمن مفهوم قوة العمل المستخدم لدى منظمة العمل الدولية.\n\nلماذا تهم المقارنة؟\nيساعد على مناقشة الفرص والعوائق أمام المشاركة الاقتصادية للنساء والاختلافات بين البلدان، مع مراعاة التعليم والأمن والرعاية الأسرية وفرص الوظائف.\n\nكيف تقرأ الترتيب؟\nقارن سنة القياس مع بيانات المشاركة العامة والتوظيف عند تفسير موقع اليمن. قد تؤثر الأعراف واحتساب العمل الأسري غير الرسمي وطرق المسوح في تقدير الحجم الفعلي للمشاركة.\n\nحدود القراءة:\nلا يساوي نسبة النساء المتوظفات بأجور أو اللواتي يملكن شركات، ولا يقيس قيمة العمل المنزلي والرعائي غير المدفوع. المرتبة وحدها لا تحدد سبب انخفاض المشاركة."},{"slug":"foreign-investment","old":"صافي التدفقات الداخلة وقد يكون سالباً؛ التقلبات تستلزم تفسيراً سياقياً.","description":"يعرض صافي تدفقات الاستثمار الأجنبي المباشر الواردة إلى الاقتصاد كنسبة من الناتج المحلي، وقد تكون القيمة موجبة أو سالبة بسبب خروج رؤوس الأموال أو تسويات التدفقات.\n\nلماذا تهم المقارنة؟\nيساعد على مقارنة وزن الاستثمارات العابرة للحدود المباشرة مع حجم اقتصاد اليمن ودول أخرى، وهو أحد جوانب بيئة التمويل والاستثمار.\n\nكيف تقرأ الترتيب؟\nاقرأ قيم السنوات المتتابعة مع الحذر من القفزات الناتجة عن صفقات كبيرة أو انخفاض الناتج المحلي. الترتيب من الأعلى إلى الأقل يصف التدفق النسبي ولا يحكم وحده على جودة الاستثمار.\n\nحدود القراءة:\nليس رصيد جميع الأصول الأجنبية ولا كل تحويل مالي من الخارج. وقد تدل القيمة السالبة على صافي تدفقات خارجة ولا تثبت غياب جميع المشروعات الأجنبية."},{"slug":"forest","old":"حصة الغابات من اليابسة؛ تتأثر بطبيعة المناخ والجغرافيا.","description":"يقيس حصة الأراضي المصنفة غابات من إجمالي مساحة اليابسة وفق تعريف نباتي ومساحي معتمد، وليس نسبة كل المساحات الخضراء.\n\nلماذا تهم المقارنة؟\nيساعد على وصف إحدى خصائص الغطاء الطبيعي ومقارنة حجم الغابات النسبي بين البلدان، مع مراعاة المناخ والتضاريس ومحدودية الأراضي الرطبة.\n\nكيف تقرأ الترتيب؟\nقارن اليمن بالدول الأخرى بوصفه اختلافاً في نوع الغطاء الأرضي، لا تقييماً عاماً لجودة البيئة. تحتاج القراءة إلى بيانات التغير الزمني والحماية والاستصلاح.\n\nحدود القراءة:\nالدول الصحراوية ليست بالضرورة أقل نجاحاً بيئياً لمجرد انخفاض حصة الغابات، ولا يقيس المؤشر جودة الغابة أو الأشجار خارج التصنيف أو صحة التنوع الحيوي."},{"slug":"inflation","old":"التغير السنوي في أسعار المستهلك؛ لا تعني القيمة الأصغر دائماً وضعاً أفضل.","description":"يقيس تضخم أسعار المستهلك التغير السنوي في مؤشر أسعار سلة سلع وخدمات استهلاكية، وفق مصدر الأسعار والمنهج الإحصائي المعتمد.\n\nلماذا تهم المقارنة؟\nيفيد في متابعة الضغوط العامة على القوة الشرائية ومقارنة تسارع ارتفاع الأسعار في اليمن بالدول الأخرى، مع الحاجة إلى النظر إلى الأجور والإنفاق الضروري.\n\nكيف تقرأ الترتيب؟\nتراجع معدل التضخم الموجب يعني أن الأسعار غالباً ترتفع بوتيرة أبطأ لا أنها انخفضت. وقيمة سالبة تعبر عن انخفاض مستوى الأسعار وفق تعريف المؤشر، لكنها ليست تلقائياً وضعاً اقتصادياً أفضل.\n\nحدود القراءة:\nلا يساوي تغير سعر كل سلعة أو تكلفة المعيشة لفئة بعينها، ولا يوضح فروق الأسعار بين محافظات اليمن. وقد تكون سنة البيانات المتاحة قديمة جداً مقارنة بظروف السوق الحالية."},{"slug":"internet","old":"نسبة الأفراد الذين يستخدمون الإنترنت.","description":"يقيس نسبة الأفراد الذين يستخدمون الإنترنت ضمن الفترة المرجعية للجهة الناشرة، ويختلف عن عدد شرائح الهاتف أو الاشتراكات المسجلة.\n\nلماذا تهم المقارنة؟\nيساعد على فهم اتساع الوصول إلى المعلومات والخدمات الرقمية وفرص التعلم والعمل عبر الشبكة. والمقارنة مع الدول الأخرى تكشف تفاوت الاستخدام دون افتراض تشابه ظروف الاتصال.\n\nكيف تقرأ الترتيب؟\nاقرأ نسبة اليمن وفق سنة القياس مع تغطية الدول الأخرى، ثم قارنها باشتراكات الهاتف والنطاق العريض الثابت. الارتفاع النسبي للاستخدام لا يعني تحسن سرعة الاتصال أو انخفاض التكلفة.\n\nحدود القراءة:\nلا يقيّم استقرار الإنترنت أو الرقابة أو جودة الخدمة أو أسعار الباقات، ولا يخبرنا بالتفاوت داخل اليمن بين المحافظات أو الأسر؛ وقد تكون أحدث سنة متاحة أقدم من الواقع الحالي."},{"slug":"labor-participation","old":"تقديرات منظمة العمل الدولية؛ المشاركة تشمل المشتغلين والباحثين عن عمل.","description":"نسبة المشاركة في القوى العاملة هي حصة السكان بعمر 15 سنة فأكثر الذين يعملون أو يبحثون عن عمل ومتاحون له، بحسب تعريف المنظمة الإحصائية.\n\nلماذا تهم المقارنة؟\nتوضح حجم الارتباط بسوق العمل بين البالغين، ويمكن أن تساعد في قراءة فرص العمل والعوائق الاجتماعية والاقتصادية أمام المشاركة.\n\nكيف تقرأ الترتيب؟\nقارن اليمن بالدول الأخرى مع مراعاة اختلاف الالتحاق بالتعليم والتركيب العمري والوظائف غير الرسمية. الارتفاع أو الانخفاض لا يعني بالضرورة أداء اقتصادياً أفضل دون سياق.\n\nحدود القراءة:\nلا يساوي معدل التوظيف ولا يعني أن جميع المشاركين يتلقون أجراً؛ فالعاطلون الباحثون عن عمل يدخلون أيضاً. ويتأثر المؤشر بأعمار الدراسة والتقاعد وأعمال الرعاية غير المدفوعة."},{"slug":"mobile","old":"عدد الاشتراكات لا عدد الأشخاص؛ يمكن أن يتجاوز 100 اشتراك لكل مئة شخص.","description":"يعبر عن عدد اشتراكات الهاتف المحمول النشطة بحسب تعريف المصدر لكل مئة شخص، وهو عداد للاشتراكات وليس للأشخاص الفريدين.\n\nلماذا تهم المقارنة؟\nيُستخدم لقراءة انتشار البنية الخلوية وأنماط الاشتراك في الاتصالات، ويمكن أن يكمل مؤشرات الاستخدام الفعلي للإنترنت والتحول الرقمي.\n\nكيف تقرأ الترتيب؟\nقارن اليمن والدول الأخرى مع مراعاة أن شخصاً واحداً قد يمتلك أكثر من شريحة، وأن الرقم قد يتجاوز مئة اشتراك لكل مئة شخص. التغير التاريخي قد يتأثر بطريقة احتساب الاشتراكات النشطة.\n\nحدود القراءة:\nلا يثبت أن كل فرد يمتلك هاتفاً أو يستخدم الإنترنت، ولا يقيس قوة الإشارة أو جودة المكالمات أو سرعة الشبكة. عدد الاشتراكات لا يكشف توزعها بين المناطق."},{"slug":"renewable-energy","old":"يشمل تعريف المصدر أنماطاً مختلفة للطاقة المتجددة؛ لا يعكس وحده جودة منظومة الطاقة.","description":"يمثل حصة مصادر الطاقة المتجددة من الاستهلاك النهائي الإجمالي للطاقة وفق التعريف الدولي، وقد تتضمن أنواعاً مختلفة من الطاقة الحيوية والمتجددة.\n\nلماذا تهم المقارنة؟\nيساعد على فهم مزيج الطاقة في الاقتصاد، وطبيعة الاعتماد النسبي على المصادر المتجددة مقارنة بالدول الأخرى.\n\nكيف تقرأ الترتيب؟\nاقرأ النسبة مع أنواع الوقود الداخلة في المصدر؛ فقد ترتفع نسبة بلد يعتمد على الكتلة الحيوية التقليدية دون أن يعني ذلك انتشار الشبكات الشمسية الحديثة. المقارنة وحدها لا تقيس موثوقية الخدمة.\n\nحدود القراءة:\nالنسبة لا تساوي حصة الكهرباء الشمسية ولا عدد المنازل المزودة بألواح، ولا تثبت أن استخدام جميع المصادر المتجددة مستدام أو خالٍ من الآثار الصحية."},{"slug":"sanitation","old":"السكان الذين يستخدمون خدمات صرف صحي أساسية على الأقل.","description":"يعبر المؤشر عن نسبة السكان الذين يستخدمون مرافق صرف صحي محسّنة وغير مشتركة مع أسر أخرى، وفق مفهوم الصرف الصحي الأساسي.\n\nلماذا تهم المقارنة؟\nيساعد على فهم أحد متطلبات الوقاية من الأمراض والكرامة الصحية، ويُقرأ مع جودة المياه وتوزيع السكان بين الريف والحضر.\n\nكيف تقرأ الترتيب؟\nقارن اليمن والدول الأخرى وفق التعريف نفسه وسنة متوافقة. الزيادة في الوصول الأساسي تحسن التغطية المحددة، لكنها لا تصف معالجة الفضلات عبر منظومة الصرف كاملة.\n\nحدود القراءة:\nالمؤشر لا يقيس إدارة الحمأة أو جودة محطات المعالجة أو سلامة المياه الجوفية بصورة مباشرة، ولا يحدد ما إذا كانت شبكات المدن تعمل دون انقطاع."},{"slug":"unemployment","old":"تقديرات منظمة العمل الدولية المنمذجة؛ لا تشمل كل أشكال العمل غير الكافي.","description":"معدل البطالة هو نسبة من لا يعملون ويبحثون عن عمل ومتاحون له من إجمالي قوة العمل، وفق تقديرات منظمة العمل الدولية في سلسلة البنك الدولي.\n\nلماذا تهم المقارنة؟\nيوضح جانباً من صعوبة الحصول على العمل ويساعد على مقارنة اليمن بالدول الأخرى بعد تطبيق مفهوم إحصائي موحد نسبياً، مع أهمية دراسة بطالة الشباب والعمل غير الرسمي.\n\nكيف تقرأ الترتيب؟\nيُقرأ هذا المعيار من الأقل إلى الأعلى، لكن ينبغي النظر إلى المشاركة الاقتصادية؛ فقد يبدو معدل البطالة أقل في بلد يغادر فيه كثير من الناس قوة العمل ولا يبحثون عن وظيفة.\n\nحدود القراءة:\nلا يشمل كل من لا يتقاضى راتباً أو يعمل ساعات قليلة، ولا يقيس جودة الوظائف أو الفقر. وفي ظروف النزاع قد تعتمد السلسلة على تقديرات نموذجية أكثر من مسوح منتظمة."}]'::jsonb) AS item),
updated AS (
 UPDATE public.ranking_indicators i SET description=input.item->>'description',updated_at=now()
 FROM input WHERE i.slug=input.item->>'slug' AND i.is_published AND i.description=input.item->>'old'
 RETURNING i.slug
) SELECT (SELECT count(*) FROM input) AS planned,(SELECT count(*) FROM updated) AS updated;
